(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.035-t*0.5)*8 + Math.cos(sy*0.028+t*0.4)*6;
  const w2y = Math.cos(sy*0.03+t*0.45)*8 + Math.sin(sx*0.025-t*0.55)*6;
  const fx = sx + w2x, fy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.5],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.6],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.4],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.45],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.55],
    [80+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.3+4)*50, 0.11, 2.1, 0.35],
    [400+Math.cos(t*0.45+2)*60, 220+Math.sin(t*0.65+1)*40, 0.13, 1.4, 0.65]
  ];
  let aS=0, iS=0, i2S=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    i2S += Math.cos(d*f*0.5-t*sp*0.4+3.0)*w*0.5;
  }
  const aN=aS/3.2, iN=iS/3.2, i2N=i2S/3.2;
  const bg = (Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2 + Math.sin((fx+fy)*0.12+t*2.5)*0.2 + Math.sin((fx-fy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((fx-cx)**2+(fy-cy)**2), ang = Math.atan2(fy-cy, fx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const micro = Math.sin(fx*0.3+t*3)*Math.sin(fy*0.35-t*2.5)*0.15;
  const turb = Math.sin(Math.sin(fx*0.08+t)*3+Math.cos(fy*0.06-t*1.3)*2+t*0.7)*0.25;
  const reaction = Math.tanh((aN - iN*0.7 - i2N*0.3 + bg*0.3 + spiral + micro + turb)*2.0);
  const cell = Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.3;
  const vein = Math.abs(Math.sin(fx*0.08+Math.sin(fy*0.05+t*0.3)*3))*Math.abs(Math.sin(fy*0.09+Math.cos(fx*0.04-t*0.2)*2))*0.4;
  const blend = reaction*0.55 + cell*0.2 + vein*0.15 + turb*0.1;
  const v = blend*0.5+0.5;
  const pal = [[5,10,42],[12,40,82],[18,85,120],[30,140,135],[80,175,145],[180,195,90],[220,170,65],[215,110,60],[175,55,70],[100,25,60],[40,12,55],[5,10,42]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge = Math.abs(reaction)>0.65?1.12:Math.abs(reaction)<0.15?0.88:1.0;
  const shimmer = 1.0+Math.sin(ang*5+t*4)*0.03*Math.abs(reaction);
  const m = lum*edge*shimmer;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
